renderCourseOverview=function(){
 stopScenarioAudio();state.onOverview=true;els.kicker.textContent="Course Overview";els.title.textContent="Fraud and Disputes in AI-Mediated Commerce";els.status.textContent="Getting started";
 var topics=lessons.map(function(l,i){return "<article><span>"+String(i+1).padStart(2,"0")+"</span><h5>"+esc(l.title)+"</h5><p>"+esc(l.purpose)+"</p></article>";}).join("");
 els.main.innerHTML="<section class=\"screen-panel course-overview-screen\"><span class=\"screen-eyebrow\">Course Overview</span><h3>Managing Risk When AI Agents Influence Commerce</h3><p class=\"overview-lead\">Agent-mediated transactions introduce new ways to impersonate trusted actors, manipulate agent decisions, distort commerce data, create mismatches with customer intent, and complicate recovery. This course extends established fraud and dispute practices into that environment.</p><div class=\"overview-section\"><h4>What This Course Covers</h4><div class=\"overview-topic-grid\">"+topics+"</div></div><div class=\"overview-outcomes\"><h4>By the End of This Course, You Will Be Able To:</h4><ul><li>Distinguish legitimate agents from impersonators, malicious bots, and compromised automation.</li><li>Recognize manipulated prompts, tools, feeds, offers, and transaction terms.</li><li>Reconstruct customer intent and build evidence for agent-related disputes.</li><li>Apply rail-aware containment, recovery, and cross-functional incident controls.</li></ul></div></section>";
 els.back.disabled=true;els.next.disabled=false;els.next.textContent=hasMeaningfulCourseProgress()?"Continue Course →":"Begin Lesson 1 →";els.indicator.textContent="Course Overview";els.bar.style.width="0%";els.pct.textContent="0%";renderOverviewNav();els.main.focus();window.scrollTo(0,0);save();
};
