 var controls=[["Verify the actor","Use trusted identity evidence, freshness, replay resistance, and behavior."],["Protect the agent","Treat retrieved content as untrusted and constrain tools through least privilege."],["Protect commerce data","Preserve provenance, versions, and the exact offer that shaped the decision."],["Reconstruct intent","Link mandate, cart, confirmation, payment, and fulfillment evidence."],["Contain quickly","Stop remaining value delivery and activate the correct recovery path."],["Assess responsibility","Use facts, contracts, rules, control ownership, and jurisdiction."]];
